   132  static bool objc_build_refs(RCoreObjc *objc) {
   133          ut64 off;
   134          if (!objc->_const || !objc->_selrefs) {
   135                  return false;
   136          }
   137
   138          const ut64 va_const = objc->_const->vaddr;
   139          size_t ss_const = objc->_const->vsize;
   140          const ut64 va_selrefs = objc->_selrefs->vaddr;
   141          size_t ss_selrefs = objc->_selrefs->vsize;
   142          // TODO: check if ss_const or ss_selrefs are too big before going further
   143          size_t maxsize = R_MAX (ss_const, ss_selrefs);
   144          maxsize = R_MIN (maxsize, objc->file_size);
   145          if (ss_const > maxsize) {
   146                  if (objc->core->bin->verbose) {
   147                          R_LOG_WARN ("aao: Truncating ss_const from %u to %u", (int)ss_const, (int)maxsize);
   148                  }
   149                  ss_const = maxsize;
   150          }
   151          if (ss_selrefs > maxsize) {
   152                  if (objc->core->bin->verbose) {
   153                          R_LOG_WARN ("aao: Truncating ss_selrefs from %u to %u", (int)ss_selrefs, (int)maxsize);
   154                  }
   155                  ss_selrefs = maxsize;
   156          }
   157          ut8 *buf = calloc (1, maxsize);
   158          if (!buf) {
   159                  return false;
   160          }
   161          const size_t word_size = objc->word_size; // assuming 8 because of the read_le64
   162          if (!r_io_read_at (objc->core->io, objc->_const->vaddr, buf, ss_const)) {
   163                  R_LOG_WARN ("aao: Cannot read the whole const section %u", (unsigned int)ss_const);
   164                  return false;
   165          }
   166          for (off = 0; off + word_size < ss_const && off + word_size < maxsize; off += word_size) {
   167                  ut64 va = va_const + off;
   168                  ut64 xrefs_to = (word_size == 8)? r_read_le64 (buf + off): r_read_le32 (buf + off);
   169                  if (isValid (xrefs_to)) {
   170                          array_add (objc, va, xrefs_to);
   171                  }
   172          }
   173          if (!r_io_read_at (objc->core->io, va_selrefs, buf, ss_selrefs)) {
   174                  R_LOG_WARN ("aao: Cannot read the whole selrefs section");
   175                  return false;
   176          }
   177          for (off = 0; off + word_size < ss_selrefs && off + word_size < maxsize; off += word_size) {
   178                  ut64 va = va_selrefs + off;
   179                  ut64 xrefs_to = (word_size == 8)? r_read_le64 (buf + off): r_read_le32 (buf + off);
   180                  if (isValid (xrefs_to)) {
   181                          array_add (objc, xrefs_to, va);
   182                  }
   183          }
   184          free (buf);
   185          return true;
